input.command:
cd /tmp && uv run --no-project --with pyjwt python - <<'EOF' 2>&1 | tail -8
import jwt, warnings, datetime as d
print(jwt.__version__)
warnings.simplefilter("error")
try:
    jwt.encode({"sub":"x","exp":d.datetime.now(d.UTC)}, "short", "HS256"); print("short key ok")
except Exception as e: print("short key:", type(e).__name__, e)
try:
    jwt.decode(jwt.encode({"sub":1}, "k"*32, "HS256"), "k"*32, algorithms=["HS256"]); print("int sub ok")
except Exception as e: print("int sub:", type(e).__name__, e)
EOF

